135	// TestFactsReviewRefusesContradictoryFlags is the regression for a resolver
136	// whose switch tested apply before reject: asking it to both apply and reject
137	// the same proposal settled the apply half, dropped the reject half without a
138	// word, and reported "resolved 1 proposal(s)". The user was told a decision
139	// landed while the opposite one actually did.
140	func TestFactsReviewRefusesContradictoryFlags(t *testing.T) {
141		newFixture := func(t *testing.T) (verifyFixture, factProposal) {
142			t.Helper()
143			f := newVerifyFixture(t)
144			paths := normalizeFactPaths([]string{"ops.deploy.strategy"})
145			target := factRecord{
146				ID: factRecordID("deploys use blue-green cutover", paths), Paths: paths,
147				Text: "deploys use blue-green cutover", Branch: "main", Origin: factstore.OriginDistilled,
148				Status: factStatusActive, CreatedAt: f.now, UpdatedAt: f.now,
149			}
150			candidate := factRecord{
151				ID: factRecordID("deploys use in-place rolling restart", paths), Paths: paths,
152				Text: "deploys use in-place rolling restart", Branch: "main", Origin: factstore.OriginDistilled,
153				Status: factStatusActive, CreatedAt: f.now, UpdatedAt: f.now,
154			}
155			f.writeFacts(t, "main", []factRecord{target, candidate})
156			proposal := factProposal{
157				Action: factActionSupersede, CandidateID: candidate.ID, TargetID: target.ID, Branch: "main",
158			}
159			if err := writeFactProposals(f.storage.BrainDir, "main", []factProposal{proposal}); err != nil {
160				t.Fatal(err)
161			}
162			return f, proposal
163		}
164	
165		// One proposal, and every way of asking for it to be settled two ways at once.
166		contradictions := func(id string) map[string][]string {
167			return map[string][]string{
168				"apply and reject the same id": {"--apply", id, "--reject", id},
169				"apply-all and reject-all":     {"--apply-all", "--reject-all"},
170				"apply-all and reject an id":   {"--apply-all", "--reject", id},
171				"reject-all and apply an id":   {"--reject-all", "--apply", id},
172			}
173		}
174	
175		f, proposal := newFixture(t)
176		for name, flags := range contradictions(proposal.CandidateID) {
177			t.Run(name, func(t *testing.T) {
178				f, proposal := newFixture(t)
179				args := append([]string{"facts", "review"}, flags...)
180				out, err := execute(t, NewRootCommand(f.opts), args...)
181				if err == nil {
182					t.Fatalf("contradictory flags were accepted:\n%s", out)
183				}
184	
185				// A refusal must be total: the queue and the facts stay as they were,
186				// so the caller can re-run with the half they meant.
187				queued, qErr := loadFactProposals(f.storage.BrainDir, "main")
188				if qErr != nil {
189					t.Fatal(qErr)
190				}
191				if len(queued) != 1 || queued[0].CandidateID != proposal.CandidateID {
192					t.Fatalf("refused review still settled the queue: %+v", queued)
193				}
194				facts, loadErr := factstore.Load(f.storage.BrainDir, "main")
195				if loadErr != nil {
196					t.Fatal(loadErr)
197				}
198				for _, fact := range facts {
199					if fact.Status != factStatusActive {
200						t.Fatalf("refused review still mutated facts: %+v", fact)
201					}
202				}
203			})
204		}
205	
206		// The control: one side alone still settles, so the refusal is about the
207		// contradiction and not about the flags themselves.
208		out, err := execute(t, NewRootCommand(f.opts), "facts", "review", "--apply", proposal.CandidateID)
209		if err != nil {
210			t.Fatalf("a single --apply should still work: %v\n%s", err, out)
211		}
212		if !strings.Contains(out, "resolved 1 proposal(s)") {
213			t.Fatalf("unexpected review summary:\n%s", out)
214		}
215	}
