func reconcileChunkCandidates(ctx context.Context, run base.DistillAgentRunner, agentArgs []string, candidates, active []factRecord, repoDir string, timeout time.Duration) ([]factAction, []string) {
	existing, capped := activeFactsAtPaths(active, candidatePathSet(candidates))
	if len(existing) == 0 {
		actions := make([]factAction, len(candidates))
		for i, c := range candidates {
			actions[i] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: c}
		}
		return actions, nil
	}
	var warnings []string
	if capped {
		warnings = append(warnings, fmt.Sprintf("reconcile: more than %d existing memories at these paths; comparing against the %d most recent", maxReconcileExisting, maxReconcileExisting))
	}
	out, err := run(ctx, repoDir, agentArgs, reconcileInput(candidates, existing), timeout)
	if err != nil {
		warnings = append(warnings, fmt.Sprintf("reconcile agent failed, leaving %d candidates staged: %v", len(candidates), err))
		actions := make([]factAction, len(candidates))
		for i, c := range candidates {
			actions[i] = factAction{Kind: factActionDefer, Candidate: c}
		}
		return actions, warnings
	}
	actions, parseWarnings := parseReconcileActions(out, candidates, existing)
	return actions, append(warnings, parseWarnings...)
}
